import { useMemo, useState, type FormEvent, type ReactNode } from 'react'
import { useNavigate, useSearchParams } from 'react-router-dom'
import type { ReviewState } from '../../../app/fixtureSession'
import type { ScreenDefinition, ScreenRole } from '../../../app/screenManifest'
import { expandLocalTable, isStressGenerated } from '../../../app/localStressData'
import { Badge, Button, Field, Info, inputCls, PageHeader, Table, Td, Th } from '../../../components/ui'
import { EmptyState, FilterBar, FixtureNotice, InlineMessage, LoadingState, StickyActions, SummaryStrip, WorkSection } from '../../../components/workspace'
import { initialCows, MANAGER, type CowSeed } from '../../../data/cowsData'
import { loadCatalogueItems, type VaccineItem } from '../../catalogue/catalogueStore'

const STORAGE_KEY = 'beefcare-ui-demo'
const SELECTED_CATTLE = 'selected-cattle'
const SELECTED_VACCINATION = 'selected-vaccination'
const SELECTED_VACCINATIONS = 'selected-vaccinations'
const ROUTE_OPTIONS = ['Tiêm bắp', 'Tiêm dưới da', 'Uống', 'Xịt mũi', 'Khác'] as const
type Route = typeof ROUTE_OPTIONS[number] | 'Không rõ'
type VaccinationStatus = 'PLANNED' | 'ADMINISTERED' | 'DEFERRED' | 'CANCELLED' | 'VOIDED'
type VaccinationSource = 'ON_FARM' | 'HISTORICAL'
type Result = 'ADMINISTERED' | 'DEFERRED'
type Vaccination = {
  id: string; code: string; vaccine: string; dose: string; planned: string; administered?: string; batch: string; status: VaccinationStatus
  source?: VaccinationSource; route?: string; amount?: string; withdrawalDays?: number; withdrawal?: string; vaccinator?: string; by?: string
  reaction?: string; healthCaseRef?: string; note?: string; scheduleId?: string; scheduledPriorStatus?: 'PLANNED' | 'DEFERRED'
  recordStatus?: 'VALID' | 'VOIDED'; revision?: number; updatedBy?: string; deferDate?: string
}
type ScheduleDraft = {
  id?: string; name?: string; vaccine?: string; start?: string; doses?: string; interval?: string; booster?: boolean; boosterMonths?: string
  pens?: string[]; groups?: string[]; stages?: string[]; exclude?: string; manualExcluded?: string[]; individualCodes?: string[]; matching?: string[]
  active?: boolean; stopReason?: string
}
type Revision = { id: string; originalId: string; action: 'CORRECT' | 'VOID'; reason: string; actor: string; revision: number; before: Vaccination; after?: Vaccination; createdAt: string }

const fallback = (): Vaccination[] => [
  { id: 'vax-125-1', code: 'BC-000125', vaccine: 'LMLM', dose: 'Mũi 2', planned: '2026-11-05', batch: 'L-221', status: 'PLANNED', scheduleId: 'schedule-fmd-2026' },
  { id: 'vax-142-1', code: 'BC-000142', vaccine: 'LMLM', dose: 'Mũi 1', planned: '2026-10-05', administered: '2026-10-05T08:20', batch: 'L-221', status: 'ADMINISTERED', recordStatus: 'VALID', source: 'ON_FARM', route: 'Tiêm bắp', amount: '2 ml', withdrawalDays: 0, vaccinator: MANAGER, by: MANAGER, scheduleId: 'schedule-fmd-2026', scheduledPriorStatus: 'PLANNED' },
  { id: 'vax-203-1', code: 'BC-000203', vaccine: 'Tụ huyết trùng', dose: 'Mũi 1', planned: '2026-10-28', batch: 'L-218', status: 'DEFERRED', note: 'Bò đang theo dõi sức khỏe', scheduleId: 'schedule-haem-2026' },
]
const readRoot = (): Record<string, any> => { try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}') as Record<string, any> } catch { return {} } }
const read = <T,>(key: string, fallbackValue: T): T => (readRoot().account?.[key] as T) ?? fallbackValue
const write = (key: string, value: unknown) => { const root = readRoot(); localStorage.setItem(STORAGE_KEY, JSON.stringify({ ...root, account: { ...(root.account || {}), [key]: value } })) }
const clearVaccinationSelection = () => { write(SELECTED_VACCINATION, null); write(SELECTED_VACCINATIONS, []) }
const recomputeWithdrawal = (code: string, records: Vaccination[]) => { const latest = records.filter((item) => item.code === code && item.status === 'ADMINISTERED' && (item.recordStatus || 'VALID') === 'VALID' && item.withdrawal).sort((a, b) => (a.withdrawal || '').localeCompare(b.withdrawal || '')).pop()?.withdrawal; const summary = read<Record<string, string>>('vaccination-withdrawal-summary', {}); if (latest) summary[code] = latest; else delete summary[code]; write('vaccination-withdrawal-summary', summary); write('cattle-preview', cows().map((cow) => cow.code === code ? { ...cow, withdrawalUntil: latest } : cow)) }
const cows = () => expandLocalTable('vaccination-cattle', read<CowSeed[]>('cattle-preview', initialCows))
const rows = () => {
  const expanded = expandLocalTable('vaccination-records', read<Vaccination[]>('vaccination-preview', fallback()))
  const cattle = cows().filter((cow) => cow.status === 'ACTIVE')
  return expanded.map((row, index) => isStressGenerated(row) && cattle.length ? { ...row, code: cattle[index % cattle.length].code } : row)
}
const activeCattle = () => cows().filter((cow) => cow.status === 'ACTIVE')
const isManager = (role?: ScreenRole) => role === 'manager'
const localNow = () => { const now = new Date(); const pad = (value: number) => String(value).padStart(2, '0'); return { date: `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`, time: `${pad(now.getHours())}:${pad(now.getMinutes())}` } }
const localToday = () => localNow().date
const dateLabel = (value?: string) => value ? new Date(`${value.slice(0, 10)}T00:00:00`).toLocaleDateString('vi-VN') : '—'
const dateTimeLabel = (value?: string) => value ? `${dateLabel(value)}${value.includes('T') ? ` · ${value.split('T')[1].slice(0, 5)}` : ''}` : '—'
const addDays = (value: string, days: number) => { const date = new Date(`${value}T00:00:00`); date.setDate(date.getDate() + days); return date.toISOString().slice(0, 10) }
const addMonths = (value: string, months: number) => { const date = new Date(`${value}T00:00:00`); date.setMonth(date.getMonth() + months); return date.toISOString().slice(0, 10) }
const dayDiff = (value: string) => Math.round((new Date(`${value}T00:00:00`).getTime() - new Date(`${localToday()}T00:00:00`).getTime()) / 86400000)
const doseBucket = (row: Vaccination) => { if (row.status === 'ADMINISTERED') return 'DONE'; if (row.status === 'DEFERRED') return 'DEFERRED'; if (row.status === 'CANCELLED') return 'CANCELLED'; if (row.status === 'VOIDED') return 'VOIDED'; if (dayDiff(row.planned) < 0) return 'OVERDUE'; if (dayDiff(row.planned) <= 7) return 'DUE7'; return 'UPCOMING' }
const statusLabel = (row: Vaccination) => ({ ADMINISTERED: 'Đã tiêm', DEFERRED: 'Đã hoãn', CANCELLED: 'Lịch đã hủy', VOIDED: 'Bản ghi đã hủy', OVERDUE: 'Quá hạn', DUE7: 'Trong 7 ngày', UPCOMING: 'Sắp tới' } as Record<string, string>)[doseBucket(row)]
const statusTone = (row: Vaccination) => doseBucket(row) === 'DONE' ? 'ok' : ['VOIDED', 'CANCELLED', 'OVERDUE'].includes(doseBucket(row)) ? 'err' : doseBucket(row) === 'DEFERRED' ? 'warn' : 'info'
const cowByCode = (code: string) => cows().find((cow) => cow.code === code)
const entryDate = (cow?: CowSeed) => { const value = (cow as (CowSeed & { entryDate?: string }) | undefined)?.entryDate || cow?.importRecord?.date || ''; const match = value.match(/(\d{4})-(\d{2})-(\d{2})|(\d{2})\/(\d{2})\/(\d{4})/); return match ? match[1] ? `${match[1]}-${match[2]}-${match[3]}` : `${match[6]}-${match[5]}-${match[4]}` : '' }
const normaliseVaccine = (value: string) => value.toLowerCase().replace(/^vaccine\s+/, '').trim()
const vaccineCatalog = () => loadCatalogueItems('vaccines') as VaccineItem[]
const isActiveVaccine = (value: string) => { const match = vaccineCatalog().find((item) => normaliseVaccine(item.name) === normaliseVaccine(value) || item.code === value); return Boolean(match?.status === 'ACTIVE') }
const vaccineChoices = () => vaccineCatalog().filter((item) => item.status === 'ACTIVE').map((item) => normaliseVaccine(item.name))
const isValidRoute = (value?: string): value is Route => Boolean(value && ((ROUTE_OPTIONS as readonly string[]).includes(value) || value === 'Không rõ'))
const isScheduleEligible = (row?: Vaccination) => Boolean(row && (row.status === 'PLANNED' || row.status === 'DEFERRED'))
const isHistoryRecord = (row: Vaccination) => row.status === 'ADMINISTERED' || row.status === 'VOIDED'
const sortByDate = (list: Vaccination[]) => [...list].sort((a, b) => (a.administered || a.planned).localeCompare(b.administered || b.planned) || a.code.localeCompare(b.code) || a.dose.localeCompare(b.dose))
const selectedUrl = (route: string, id: string) => `${route}?id=${encodeURIComponent(id)}`
const scheduleLabel = (id?: string) => {
  if (!id) return 'Không thuộc lịch'
  const schedules = read<ScheduleDraft[]>('vaccination-schedules', [])
  const draft = read<ScheduleDraft>('vaccination-schedule-draft', {})
  const match = [...schedules, draft].find((item) => item.id === id && item.name)
  if (match?.name) return match.name
  if (id === 'schedule-fmd-2026') return 'LMLM định kỳ 2026'
  if (id === 'schedule-haem-2026') return 'Tụ huyết trùng 2026'
  return 'Lịch tiêm đã lưu'
}

function Shell({ screen, children, actions }: { screen: ScreenDefinition; children: ReactNode; actions?: ReactNode }) { return <div className="flex w-full min-w-0 flex-col gap-6"><PageHeader title={screen.viTitle} sub="Dữ liệu lịch tiêm được cập nhật ngay sau mỗi thao tác." badge={<FixtureNotice />}>{actions}</PageHeader>{children}</div> }
function ReadState({ state, loadingLabel, errorLabel, empty }: { state: ReviewState; loadingLabel: string; errorLabel: string; empty?: ReactNode }) { if (state === 'loading') return <LoadingState label={loadingLabel} />; if (state === 'error') return <InlineMessage tone="err" title="Không thể tải dữ liệu">{errorLabel}</InlineMessage>; if (state === 'empty' && empty) return <>{empty}</>; return null }
function ManagerOnly({ screen, role, children }: { screen: ScreenDefinition; role?: ScreenRole; children: ReactNode }) { return isManager(role) ? <>{children}</> : <Shell screen={screen}><InlineMessage tone="warn">Chỉ Quản lý được tạo, sửa hoặc dừng lịch tiêm.</InlineMessage></Shell> }

function Schedule({ screen, role, state }: { screen: ScreenDefinition; role?: ScreenRole; state: ReviewState }) {
  const nav = useNavigate(); const [query, setQuery] = useState(''); const [vaccine, setVaccine] = useState('ALL'); const [tab, setTab] = useState('ALL'); const [selected, setSelected] = useState<string[]>([]); const all = sortByDate(rows()); const tabs = [{ id: 'ALL', label: 'Tất cả' }, { id: 'OVERDUE', label: 'Quá hạn' }, { id: 'DUE7', label: 'Trong 7 ngày' }, { id: 'UPCOMING', label: 'Sắp tới' }, { id: 'DEFERRED', label: 'Đã hoãn' }, { id: 'DONE', label: 'Đã tiêm' }]; const visible = useMemo(() => all.filter((item) => (!query || `${item.code} ${item.vaccine} ${item.dose} ${cowByCode(item.code)?.tag || ''}`.toLowerCase().includes(query.toLowerCase())) && (vaccine === 'ALL' || item.vaccine === vaccine) && (tab === 'ALL' || doseBucket(item) === tab)), [all, query, vaccine, tab]); const count = (key: string) => key === 'ALL' ? all.length : all.filter((item) => doseBucket(item) === key).length; const readOnly = state === 'read-only' || !isManager(role); const open = (item: Vaccination) => { write(SELECTED_VACCINATION, { id: item.id }); write(SELECTED_CATTLE, { code: item.code }); nav(selectedUrl(item.status === 'ADMINISTERED' || item.status === 'VOIDED' ? '/ui/scr-49' : '/ui/scr-48', item.id)) }; const toggle = (row: Vaccination) => { if (!isScheduleEligible(row) || readOnly) return; setSelected((current) => { if (current.includes(row.id)) return current.filter((value) => value !== row.id); if (current.some((id) => all.find((item) => item.id === id)?.code === row.code)) return current; return [...current, row.id] }) }; const startDefer = () => { const eligible = selected.filter((id) => isScheduleEligible(all.find((row) => row.id === id))); if (eligible.length) { write(SELECTED_VACCINATIONS, eligible); nav('/ui/scr-50') } }; const empty = <Shell screen={screen}><EmptyState title="Chưa có liều tiêm phù hợp" description="Tạo lịch tiêm hoặc thử bỏ bớt bộ lọc để xem các liều trong đàn." actionLabel={isManager(role) ? 'Quản lý lịch tiêm' : undefined} onAction={isManager(role) ? () => nav('/ui/scr-47') : undefined} /></Shell>; const readState = ReadState({ state, loadingLabel: 'Đang tải lịch tiêm…', errorLabel: 'Lịch tiêm tạm thời không khả dụng.', empty }); if (readState) return readState
  return <Shell screen={screen} actions={<><Button onClick={() => nav('/ui/scr-51')}>Lịch sử toàn đàn</Button>{isManager(role) && state !== 'read-only' && <><Button onClick={() => nav('/ui/scr-47')}>Quản lý lịch</Button><Button variant="primary" onClick={() => { clearVaccinationSelection(); nav('/ui/scr-48') }}>Ghi nhận tiêm</Button></>}</>}>
    {state === 'read-only' && <InlineMessage tone="info">Chế độ chỉ đọc: bạn vẫn có thể xem lịch và mở hồ sơ, nhưng không thể ghi nhận, hoãn hoặc quản lý lịch.</InlineMessage>}
    <div className="flex min-w-0 flex-wrap gap-2 border-b border-rule pb-3">{tabs.map((item) => <Button key={item.id} small variant={tab === item.id ? 'primary' : 'default'} onClick={() => setTab(item.id)}>{item.label} ({count(item.id)})</Button>)}</div>
    <FilterBar><Field id="vaccination-query" label="Tìm bò, thẻ hoặc vaccine"><input id="vaccination-query" aria-label="Tìm bò, thẻ hoặc vaccine" className={inputCls} value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Ví dụ: BC-000125 hoặc LMLM" /></Field><Field id="vaccination-vaccine-filter" label="Vaccine"><select id="vaccination-vaccine-filter" aria-label="Lọc vaccine" className={inputCls} value={vaccine} onChange={(event) => setVaccine(event.target.value)}><option value="ALL">Tất cả vaccine</option>{[...new Set(all.map((item) => item.vaccine))].map((item) => <option key={item}>{item}</option>)}</select></Field><Button small onClick={() => { setQuery(''); setVaccine('ALL'); setTab('ALL') }}>Xóa lọc</Button></FilterBar>
    <SummaryStrip items={[{ label: 'Liều hiển thị', value: visible.length }, { label: 'Quá hạn', value: count('OVERDUE') }, { label: 'Trong 7 ngày', value: count('DUE7') }, { label: 'Đã tiêm', value: count('DONE') }]} />
    <WorkSection title="Tiến độ theo lịch" description="Mỗi lịch giữ nguyên liều đã ghi nhận; chỉ các liều đang chờ hoặc đã hoãn mới có thể chọn."><div className="grid gap-4 sm:grid-cols-3">{[...new Set(all.map((item) => item.vaccine))].map((name) => { const related = all.filter((item) => item.vaccine === name && !['CANCELLED', 'VOIDED'].includes(item.status)); const done = related.filter((item) => item.status === 'ADMINISTERED').length; return <div key={name} className="border-b border-rule pb-3"><div className="font-semibold">{name}</div><div className="mt-1 text-xs text-subtle">Đã tiêm {done}/{related.length || 0} liều</div><div className="mt-2 h-1.5 bg-chip"><div className="h-1.5 bg-brand" style={{ width: `${related.length ? Math.round(done / related.length * 100) : 0}%` }} /></div></div> })}</div></WorkSection>
    {!readOnly && selected.length > 0 && <InlineMessage tone="info">Đã chọn {selected.length} liều đang chờ hoặc đã hoãn. Liều Đã tiêm không thể chọn lại.</InlineMessage>}
    {!readOnly && <div className="flex flex-wrap gap-2"><Button small disabled={!selected.length} onClick={() => { const eligible = selected.filter((id) => isScheduleEligible(all.find((row) => row.id === id))); if (eligible.length) { write(SELECTED_VACCINATIONS, eligible); nav('/ui/scr-48') } }}>Ghi nhận {selected.length || ''} liều đã chọn</Button><Button small disabled={!selected.length} onClick={startDefer}>Hoãn {selected.length || ''} liều đã chọn</Button></div>}
    <Table wide scroll><thead><tr><Th>{!readOnly && <span className="sr-only">Chọn</span>}</Th><Th>Bò</Th><Th>Chuồng</Th><Th>Vaccine · mũi</Th><Th>Ngày dự kiến</Th><Th>Trạng thái</Th><Th>Thao tác</Th></tr></thead><tbody>{visible.map((item) => { const selectable = !readOnly && isScheduleEligible(item); return <tr key={item.id}><Td>{!readOnly && <input id={`vaccination-select-${item.id}`} aria-label={`Chọn ${item.code} ${item.vaccine} ${item.dose}`} type="checkbox" disabled={!selectable} checked={selected.includes(item.id)} onChange={() => toggle(item)} />}</Td><Td><button type="button" className="font-semibold text-brand underline-offset-2 hover:underline" onClick={() => { write(SELECTED_CATTLE, { code: item.code }); nav(selectedUrl('/ui/scr-49', item.id)) }}>{item.code}</button></Td><Td>{cowByCode(item.code)?.barn || '—'}</Td><Td>{item.vaccine} · {item.dose}</Td><Td>{dateLabel(item.planned)}</Td><Td><Badge tone={statusTone(item)}>{statusLabel(item)}</Badge></Td><Td><Button small onClick={() => open(item)}>{item.status === 'ADMINISTERED' || item.status === 'VOIDED' ? 'Mở lịch sử' : 'Ghi nhận'}</Button></Td></tr> })}</tbody></Table>
  </Shell>
}

function ScheduleEditor({ screen, role, state }: { screen: ScreenDefinition; role?: ScreenRole; state: ReviewState }) {
  const nav = useNavigate(); const saved = read<ScheduleDraft>('vaccination-schedule-draft', {}); const active = activeCattle(); const currentRows = rows(); const [name, setName] = useState(saved.name || 'LMLM định kỳ 2026'); const [vaccine, setVaccine] = useState(saved.vaccine || vaccineChoices()[0] || 'LMLM'); const [start, setStart] = useState(saved.start || addDays(localToday(), 2)); const [doses, setDoses] = useState(saved.doses || '2'); const [interval, setInterval] = useState(saved.interval || '30'); const [booster, setBooster] = useState(Boolean(saved.booster)); const [boosterMonths, setBoosterMonths] = useState(saved.boosterMonths || '12'); const [pens, setPens] = useState(saved.pens || ['A1']); const [groups, setGroups] = useState(saved.groups || ['Sinh sản']); const [stages, setStages] = useState(saved.stages || ['Bò cái sinh sản']); const [exclude, setExclude] = useState(saved.exclude || ''); const [individualCodes] = useState(saved.individualCodes || []); const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [stopReason, setStopReason] = useState('')
  const readState = ReadState({ state, loadingLabel: 'Đang tải cấu hình lịch tiêm…', errorLabel: 'Không thể tải cấu hình lịch tiêm.' }); if (readState) return readState
  if (state === 'empty') return <Shell screen={screen}><EmptyState title="Chưa có dữ liệu để lập lịch" description="Không có bò đang nuôi phù hợp để cấu hình lịch tiêm." /></Shell>
  if (state === 'read-only') return <Shell screen={screen}><InlineMessage tone="info">Chế độ chỉ đọc: cấu hình lịch tiêm không thể thay đổi.</InlineMessage></Shell>
  if (!isManager(role)) return <Shell screen={screen}><InlineMessage tone="warn">Chỉ Quản lý được tạo, sửa hoặc dừng lịch tiêm. Dữ liệu lịch vẫn được xem ở màn hình lịch tiêm.</InlineMessage></Shell>
  const toggle = (values: string[], value: string, setter: (values: string[]) => void) => setter(values.includes(value) ? values.filter((item) => item !== value) : [...values, value])
  const excludeCodes = exclude.split(',').map((item) => item.trim()).filter(Boolean); const candidates = active.filter((cow) => (!pens.length || pens.includes(cow.barn)) && (!groups.length || groups.includes(cow.purpose)) && (!stages.length || stages.includes(cow.stage)) && !excludeCodes.includes(cow.code)); const matching = [...new Map([...candidates, ...active.filter((cow) => individualCodes.includes(cow.code))].filter((cow) => !excludeCodes.includes(cow.code)).map((cow) => [cow.code, cow])).values()]; const planned = matching.flatMap((cow) => Array.from({ length: Math.max(Number(doses) || 0, 0) }, (_, index) => ({ cow, dose: `Mũi ${index + 1}`, planned: start ? addDays(start, Number(interval || 0) * index) : '' })).concat(booster && start ? [{ cow, dose: 'Mũi nhắc lại', planned: addMonths(start, Number(boosterMonths || 0)) }] : []))
  const save = (event: FormEvent) => { event.preventDefault(); setError(''); setMessage(''); const latest = rows(); if (!name.trim()) return setError('Tên lịch là bắt buộc.'); if (!isActiveVaccine(vaccine)) return setError('Chỉ được chọn vaccine đang sử dụng trong danh mục.'); if (!start) return setError('Ngày bắt đầu là bắt buộc.'); if (start < localToday()) return setError('Ngày bắt đầu không được trước hôm nay.'); if (matching.some((cow) => entryDate(cow) && start < entryDate(cow))) return setError('Ngày bắt đầu không được trước ngày nhập đàn của bò.'); if (!Number.isInteger(Number(doses)) || Number(doses) < 1 || Number(doses) > 10) return setError('Số liều phải là số nguyên từ 1 đến 10.'); if (Number(doses) > 1 && (!Number.isInteger(Number(interval)) || Number(interval) < 1 || Number(interval) > 365)) return setError('Khoảng cách liều phải là số nguyên từ 1 đến 365 khi có nhiều hơn một liều.'); if (booster && (!Number.isInteger(Number(boosterMonths)) || Number(boosterMonths) < 1 || Number(boosterMonths) > 60)) return setError('Chu kỳ nhắc lại phải từ 1 đến 60 tháng.'); if (!matching.length) return setError('Lịch phải có ít nhất một bò đang nuôi phù hợp.'); const scheduleId = saved.id || 'schedule-fmd-2026'; const draft: ScheduleDraft = { id: scheduleId, name: name.trim(), vaccine, start, doses, interval, booster, boosterMonths, pens, groups, stages, exclude, manualExcluded: [], individualCodes, matching: matching.map((cow) => cow.code), active: true }; const used = new Set<string>(); const generated = planned.flatMap((item) => { const key = `${scheduleId}|${item.cow.code}|${item.dose}`; if (used.has(key)) return []; used.add(key); const previous = latest.find((row) => row.scheduleId === scheduleId && row.code === item.cow.code && row.dose === item.dose); if (previous?.status === 'ADMINISTERED') return [previous]; return [{ ...(previous || {}), id: previous?.id || `schedule-dose-${scheduleId}-${item.cow.code}-${item.dose.replace(/\s/g, '-')}`, code: item.cow.code, vaccine, dose: item.dose, planned: previous?.status === 'DEFERRED' ? previous.planned : item.planned, batch: previous?.batch || '', status: previous?.status === 'DEFERRED' ? 'DEFERRED' as const : 'PLANNED' as const, scheduleId } as Vaccination] }); write('vaccination-schedule-draft', draft); write('vaccination-schedules', [draft]); write('vaccination-preview', [...latest.filter((row) => row.scheduleId !== scheduleId), ...generated]); setMessage(`Đã lưu lịch cho  bò (${generated.length} liều mới/còn giữ).`) }
  const stop = () => { setError(''); if (!stopReason.trim()) return setError('Lý do dừng lịch là bắt buộc.'); const scheduleId = saved.id || 'schedule-fmd-2026'; const stopped = { ...saved, id: scheduleId, active: false, stopReason }; const latest = rows(); write('vaccination-schedule-draft', stopped); write('vaccination-schedules', [stopped]); write('vaccination-preview', latest.map((item) => item.scheduleId === scheduleId && ['PLANNED', 'DEFERRED'].includes(item.status) ? { ...item, status: 'CANCELLED' as const, note: `Dừng lịch: ${stopReason}` } : item)); setMessage('Đã dừng lịch; chỉ các liều đang chờ hoặc đã hoãn được đánh dấu lịch đã hủy.'); setStopReason('') }
  const checks = (label: string, values: string[], chosen: string[], setter: (values: string[]) => void, groupId: string) => <fieldset><legend id={`${groupId}-legend`} className="mb-2 text-xs font-semibold">{label}</legend><div className="flex flex-wrap gap-3">{values.map((value) => <label key={value} className="flex items-center gap-2 text-xs"><input type="checkbox" aria-labelledby={`${groupId}-legend`} checked={chosen.includes(value)} onChange={() => toggle(chosen, value, setter)} />{value}</label>)}</div></fieldset>
  return <ManagerOnly screen={screen} role={role}><Shell screen={screen} actions={<Button onClick={() => nav('/ui/scr-46')}>Về lịch tiêm</Button>}><form id="vaccination-schedule-form" onSubmit={save} className="min-w-0 space-y-6"><InlineMessage tone="info">Lịch mới chỉ tạo liều cho bò đang nuôi. Khi sửa lịch, các liều đã tiêm và liên kết lịch/mũi được giữ nguyên.</InlineMessage><WorkSection title="Thông tin lịch"><div className="grid gap-4 md:grid-cols-3"><Field id="schedule-name" label="Tên lịch *"><input id="schedule-name" className={inputCls} maxLength={150} value={name} onChange={(event) => setName(event.target.value)} /></Field><Field id="schedule-vaccine" label="Vaccine đang sử dụng *"><select id="schedule-vaccine" className={inputCls} value={vaccine} onChange={(event) => setVaccine(event.target.value)}>{vaccineChoices().map((item) => <option key={item}>{item}</option>)}</select></Field><Field id="schedule-start" label="Ngày bắt đầu *"><input id="schedule-start" className={inputCls} type="date" min={localToday()} value={start} onChange={(event) => setStart(event.target.value)} /></Field><Field id="schedule-doses" label="Số liều *"><input id="schedule-doses" className={inputCls} type="number" min="1" max="10" step="1" value={doses} onChange={(event) => setDoses(event.target.value)} /></Field><Field id="schedule-interval" label="Khoảng cách liều (ngày)"><input id="schedule-interval" className={inputCls} type="number" min="1" max="365" step="1" value={interval} onChange={(event) => setInterval(event.target.value)} /></Field><label className="flex items-center gap-2 text-sm"><input id="schedule-booster" type="checkbox" checked={booster} onChange={(event) => setBooster(event.target.checked)} /> Có mũi nhắc lại</label>{booster && <Field id="schedule-booster-months" label="Chu kỳ nhắc lại (tháng)"><input id="schedule-booster-months" className={inputCls} type="number" min="1" max="60" step="1" value={boosterMonths} onChange={(event) => setBoosterMonths(event.target.value)} /></Field>}</div></WorkSection><WorkSection title="Phạm vi áp dụng"><div className="grid gap-5 md:grid-cols-3">{checks('Chuồng', [...new Set(active.map((cow) => cow.barn))], pens, setPens, 'schedule-pens')}{checks('Mục đích', [...new Set(active.map((cow) => cow.purpose))], groups, setGroups, 'schedule-groups')}{checks('Giai đoạn', [...new Set(active.map((cow) => cow.stage))], stages, setStages, 'schedule-stages')}</div><Field id="schedule-exclude" label="Loại trừ mã bò"><input id="schedule-exclude" className={inputCls} value={exclude} onChange={(event) => setExclude(event.target.value)} placeholder="BC-000001, BC-000002" /></Field><Info items={[["Bò phù hợp", matching.length], ["Liều dự kiến", planned.length], ["Liều đã tiêm giữ nguyên", currentRows.filter((row) => row.scheduleId === (saved.id || 'schedule-fmd-2026') && row.status === 'ADMINISTERED').length]]} /></WorkSection>{message && <InlineMessage tone="ok">{message}</InlineMessage>}{error && <InlineMessage tone="err" title="Chưa thể lưu">{error}</InlineMessage>}<StickyActions actions={<><Button type="button" onClick={() => nav('/ui/scr-46')}>Hủy</Button><Button variant="primary" type="submit">Lưu lịch tiêm</Button></>} /></form>{saved.id && saved.active !== false && <WorkSection title="Dừng lịch tiêm" description="Dừng lịch chỉ hủy các liều đang chờ hoặc đã hoãn; các liều đã tiêm vẫn được giữ nguyên."><Field id="schedule-stop-reason" label="Lý do dừng lịch *"><textarea id="schedule-stop-reason" className={inputCls} maxLength={500} rows={3} value={stopReason} onChange={(event) => setStopReason(event.target.value)} /></Field><Button variant="danger" onClick={stop}>Dừng lịch</Button></WorkSection>}</Shell></ManagerOnly>
}

function RecordVaccination({ screen, role, state }: { screen: ScreenDefinition; role?: ScreenRole; state: ReviewState }) {
  const nav = useNavigate(); const [search] = useSearchParams(); const all = rows(); const selectedId = search.get('id') || read<{ id?: string }>(SELECTED_VACCINATION, {}).id; const selectedIds = read<string[]>(SELECTED_VACCINATIONS, []); const selectedRows = selectedIds.length ? selectedIds.map((id) => all.find((row) => row.id === id)).filter((row): row is Vaccination => Boolean(row)) : selectedId ? [all.find((row) => row.id === selectedId)].filter((row): row is Vaccination => Boolean(row)) : []; const active = activeCattle(); const first = selectedRows[0]; const now = localNow(); const [codes, setCodes] = useState(selectedRows.length ? [...new Set(selectedRows.map((item) => item.code))] : [active[0]?.code || '']); const [vaccine, setVaccine] = useState(first?.vaccine || vaccineChoices()[0] || 'LMLM'); const [batch, setBatch] = useState(first?.batch || ''); const [date, setDate] = useState(now.date); const [time, setTime] = useState(now.time); const [amount, setAmount] = useState('2'); const [unit, setUnit] = useState('ml'); const [route, setRoute] = useState<Route>((first?.route as Route) || 'Tiêm bắp'); const [withdrawalDays, setWithdrawalDays] = useState('0'); const [vaccinator, setVaccinator] = useState(MANAGER); const [source, setSource] = useState<VaccinationSource>('ON_FARM'); const [results, setResults] = useState<Record<string, { result: Result; reason: string; deferDate: string }>>({}); const [reaction, setReaction] = useState(''); const [healthCaseRef, setHealthCaseRef] = useState(''); const [error, setError] = useState(''); const readOnly = state === 'read-only'; const historical = source === 'HISTORICAL'; const outcome = (code: string) => results[code] || { result: 'ADMINISTERED' as Result, reason: '', deferDate: '' }; const duplicateCodes = new Set(selectedRows.map((row) => row.code)).size !== selectedRows.length; const selectedInvalid = Boolean(selectedIds.length && selectedIds.length !== selectedRows.length) || duplicateCodes || Boolean(selectedRows.some((row) => !isScheduleEligible(row)))
  if (state === 'loading') return <LoadingState label="Đang tải biểu mẫu ghi nhận tiêm…" />; if (state === 'error') return <Shell screen={screen}><InlineMessage tone="err">Không thể tải biểu mẫu ghi nhận tiêm.</InlineMessage></Shell>; if (!isManager(role)) return <Shell screen={screen}><InlineMessage tone="warn">Chỉ Quản lý được ghi nhận tiêm phòng.</InlineMessage></Shell>
  const withdrawalEnd = historical || withdrawalDays === '' ? '' : addDays(date, Number(withdrawalDays))
  const save = (event: FormEvent) => { event.preventDefault(); setError(''); if (readOnly) return setError('Chế độ chỉ đọc không cho phép lưu.'); if (selectedInvalid) return setError('Liều đã chọn không còn ở trạng thái chờ hoặc đã hoãn, hoặc đã được xử lý; hãy tải lại lịch.'); if (!codes.length || codes.some((code) => !active.some((cow) => cow.code === code))) return setError('Chỉ được chọn bò đang nuôi.'); if (!isActiveVaccine(vaccine)) return setError('Vaccine phải đang được sử dụng trong danh mục.'); if (!date || (!historical && !time) || !vaccinator.trim()) return setError('Ngày, giờ và người tiêm là bắt buộc.'); if (date > localToday() || (time && date === localToday() && time > localNow().time)) return setError('Thời gian tiêm không được ở tương lai.'); if (codes.some((code) => entryDate(cowByCode(code)) && date < entryDate(cowByCode(code)!))) return setError('Thời gian tiêm không được trước ngày nhập đàn.'); if (!historical && !batch.trim()) return setError('Số lô là bắt buộc với vaccine tiêm tại trại.'); if (!historical && (!Number.isFinite(Number(amount)) || Number(amount) <= 0)) return setError('Liều lượng phải lớn hơn 0.'); if (!historical && (!Number.isInteger(Number(withdrawalDays)) || Number(withdrawalDays) < 0 || Number(withdrawalDays) > 365)) return setError('Thời gian ngừng thuốc phải là số nguyên từ 0 đến 365 ngày.'); if (!historical && !isValidRoute(route)) return setError('Chọn đường dùng vaccine hợp lệ.'); if (codes.some((code) => outcome(code).result === 'DEFERRED' && !outcome(code).reason.trim())) return setError('Mỗi cá thể hoãn mũi phải có lý do.'); const latest = rows(); const targetRows = selectedRows.length ? selectedRows : codes.map((code) => ({ id: '', code, vaccine, dose: 'Mũi 1', planned: date, batch: '', status: 'PLANNED', scheduleId: undefined })); const next: Vaccination[] = []; for (const [index, target] of targetRows.entries()) { const code = target.code; const result = historical ? 'ADMINISTERED' as const : outcome(code).result; const existing = latest.find((row) => row.id === target.id); if (existing && !isScheduleEligible(existing)) return setError(`Liều ${existing.dose} của ${existing.code} không còn đủ điều kiện ghi nhận.`); const duplicate = !existing && result === 'ADMINISTERED' && latest.some((row) => row.code === code && row.status === 'ADMINISTERED' && row.source === 'ON_FARM' && row.scheduleId === target.scheduleId && row.dose === target.dose); if (duplicate) return setError(`Đã có bản ghi cho ${code} · ${target.dose}; không thể tạo trùng.`); const amountValue = amount.trim() ? `${amount.trim()} ${unit}` : undefined; const onFarm = source === 'ON_FARM'; const record: Vaccination = onFarm && existing && !historical ? (result === 'DEFERRED' ? { ...existing, status: 'DEFERRED', planned: outcome(code).deferDate || existing.planned, deferDate: outcome(code).deferDate || undefined, note: outcome(code).reason || existing.note, source: undefined, route: undefined, amount: undefined, withdrawalDays: undefined, withdrawal: undefined, administered: undefined, vaccinator: undefined, by: undefined, recordStatus: undefined } : { ...existing, vaccine, batch: batch.trim(), status: 'ADMINISTERED', source, route, amount: amountValue, withdrawalDays: Number(withdrawalDays), withdrawal: withdrawalEnd, administered: `${date}${time ? `T${time}` : ''}`, vaccinator: vaccinator.trim(), by: vaccinator.trim(), note: outcome(code).reason || existing.note, recordStatus: 'VALID', scheduledPriorStatus: existing.status === 'DEFERRED' ? 'DEFERRED' : 'PLANNED' }) : (result === 'DEFERRED' ? { id: `vax-${code}-${Date.now()}-${index}`, code, vaccine, dose: target.dose || 'Mũi 1', planned: outcome(code).deferDate || target.planned || date, batch: '', status: 'DEFERRED', deferDate: outcome(code).deferDate || undefined, note: outcome(code).reason, scheduleId: target.scheduleId, scheduledPriorStatus: onFarm ? (target.status === 'DEFERRED' ? 'DEFERRED' : 'PLANNED') : undefined } : { id: `vax-${code}-${Date.now()}-${index}`, code, vaccine, dose: target.dose || 'Mũi 1', planned: target.planned || date, administered: `${date}${time ? `T${time}` : ''}`, batch: batch.trim(), status: 'ADMINISTERED', source, route: historical ? (route === 'Không rõ' ? 'Không rõ' : route) : route, amount: amountValue, withdrawalDays: historical ? undefined : Number(withdrawalDays), withdrawal: historical ? undefined : withdrawalEnd, vaccinator: vaccinator.trim(), by: vaccinator.trim(), reaction, healthCaseRef, note: outcome(code).reason, scheduleId: historical ? undefined : target.scheduleId, scheduledPriorStatus: onFarm ? (target.status === 'DEFERRED' ? 'DEFERRED' : 'PLANNED') : undefined, recordStatus: 'VALID' }); next.push(record) } write('vaccination-preview', [...latest.filter((item) => !next.some((newItem) => newItem.id === item.id)), ...next]); write(SELECTED_CATTLE, { code: codes[0] }); write(SELECTED_VACCINATIONS, []); if (next[0]) write(SELECTED_VACCINATION, { id: next[0].id }); nav(selectedUrl('/ui/scr-49', next[0]?.id || selectedId || '')) }
  return <Shell screen={screen}><form id="vaccination-record-form" onSubmit={save} className="min-w-0 space-y-6"><InlineMessage tone="info">Một bản ghi được lưu cho từng bò đã chọn. Ghi nhận tại trại sẽ hoàn tất đúng liều đang chờ hoặc đã hoãn; khai báo lịch sử không thay đổi lịch.</InlineMessage>{selectedInvalid && <InlineMessage tone="err">Liều từ lựa chọn cũ không còn hợp lệ. Hãy quay lại lịch và chọn lại.</InlineMessage>}<WorkSection title="Đối tượng tiêm"><Field id="vaccination-cattle" label="Bò được chọn *"><select id="vaccination-cattle" aria-label="Bò được chọn" className={inputCls} multiple size={Math.min(6, Math.max(3, active.length))} value={codes} disabled={readOnly || Boolean(selectedRows.length)} onChange={(event) => setCodes([...event.target.selectedOptions].map((option) => option.value))}>{active.map((cow) => <option key={cow.code} value={cow.code}>{cow.code} · {cow.name || 'Chưa đặt tên'} · {cow.barn}</option>)}</select></Field>{selectedRows.length > 0 && <Info items={[['Liều được liên kết', selectedRows.map((item) => `${item.code} · ${item.dose}`).join(', ')], ['Lịch', [...new Set(selectedRows.map((item) => scheduleLabel(item.scheduleId)))].join(', ')]]} />}<Table wide scroll><thead><tr><Th>Bò</Th><Th>Chuồng</Th><Th>Kết quả</Th><Th>Ngày mới nếu hoãn</Th><Th>Lý do nếu hoãn</Th></tr></thead><tbody>{codes.map((code) => { const value = outcome(code); return <tr key={code}><Td>{code || '—'}</Td><Td>{cowByCode(code)?.barn || '—'}</Td><Td><select id={`vaccination-result-${code}`} aria-label={`Kết quả ${code}`} className={inputCls} value={historical ? 'ADMINISTERED' : value.result} disabled={readOnly || historical} onChange={(event) => setResults((current) => ({ ...current, [code]: { ...value, result: event.target.value as Result } }))}><option value="ADMINISTERED">Tiêm</option><option value="DEFERRED">Hoãn</option></select></Td><Td><input id={`vaccination-defer-date-${code}`} aria-label={`Ngày mới nếu hoãn ${code}`} className={inputCls} type="date" min={localToday()} value={value.deferDate} disabled={readOnly || historical || value.result !== 'DEFERRED'} onChange={(event) => setResults((current) => ({ ...current, [code]: { ...value, deferDate: event.target.value } }))} /></Td><Td><input id={`vaccination-defer-reason-${code}`} aria-label={`Lý do hoãn ${code}`} className={inputCls} value={value.reason} disabled={readOnly || historical || value.result !== 'DEFERRED'} placeholder="Bắt buộc khi hoãn" onChange={(event) => setResults((current) => ({ ...current, [code]: { ...value, reason: event.target.value } }))} /></Td></tr> })}</tbody></Table></WorkSection><WorkSection title="Thông tin mũi tiêm"><div className="grid gap-4 md:grid-cols-3"><Field id="vaccination-vaccine" label="Vaccine đang sử dụng *"><select id="vaccination-vaccine" className={inputCls} value={vaccine} disabled={readOnly} onChange={(event) => setVaccine(event.target.value)}>{vaccineChoices().map((item) => <option key={item}>{item}</option>)}</select></Field><Field id="vaccination-source" label="Nguồn dữ liệu *"><select id="vaccination-source" className={inputCls} value={source} disabled={readOnly} onChange={(event) => setSource(event.target.value as VaccinationSource)}><option value="ON_FARM">Tiêm tại trại</option><option value="HISTORICAL">Khai báo lịch sử</option></select></Field><Field id="vaccination-batch" label={`Số lô ${historical ? '(nếu biết)' : '*'}`}><input id="vaccination-batch" className={inputCls} maxLength={50} value={batch} disabled={readOnly} onChange={(event) => setBatch(event.target.value)} placeholder={historical ? 'Có thể để trống nếu không rõ' : 'Ví dụ: L-221'} /></Field><Field id="vaccination-date" label="Ngày tiêm *"><input id="vaccination-date" className={inputCls} type="date" max={localToday()} value={date} disabled={readOnly} onChange={(event) => setDate(event.target.value)} /></Field><Field id="vaccination-time" label={`Giờ tiêm ${historical ? '(nếu biết)' : '*'}`}><input id="vaccination-time" className={inputCls} type="time" value={time} disabled={readOnly} onChange={(event) => setTime(event.target.value)} /></Field><Field id="vaccination-amount" label={`Liều lượng ${historical ? '(nếu biết)' : '*'}`}><div className="grid grid-cols-[1fr_100px] gap-2"><input id="vaccination-amount" aria-label="Liều lượng" className={inputCls} inputMode="decimal" value={amount} disabled={readOnly} onChange={(event) => setAmount(event.target.value)} /><select id="vaccination-unit" aria-label="Đơn vị liều lượng" className={inputCls} value={unit} disabled={readOnly} onChange={(event) => setUnit(event.target.value)}><option>ml</option><option value="dose">liều</option></select></div></Field><Field id="vaccination-route" label={`Đường dùng ${historical ? '(nếu biết)' : ''}`}><select id="vaccination-route" aria-label="Đường dùng vaccine" className={inputCls} value={route} disabled={readOnly} onChange={(event) => setRoute(event.target.value as Route)}>{historical && <option>Không rõ</option>}{ROUTE_OPTIONS.map((item) => <option key={item}>{item}</option>)}</select></Field><Field id="vaccination-withdrawal" label="Ngừng thuốc (ngày)"><input id="vaccination-withdrawal" className={inputCls} type="number" min="0" max="365" value={withdrawalDays} disabled={readOnly || historical} onChange={(event) => setWithdrawalDays(event.target.value)} /></Field><Field id="vaccination-vaccinator" label="Người tiêm *"><input id="vaccination-vaccinator" className={inputCls} maxLength={100} value={vaccinator} disabled={readOnly} onChange={(event) => setVaccinator(event.target.value)} /></Field></div><Info items={[['Ngày kết thúc ngừng thuốc', withdrawalEnd ? dateLabel(withdrawalEnd) : '—'], ['Nguồn', historical ? 'Khai báo lịch sử · không đóng liều lịch' : 'Tiêm tại trại'], ['Số bản ghi sẽ tạo', `${codes.length}`]]} /></WorkSection><WorkSection title="Phản ứng sau tiêm (tuỳ chọn)"><div className="grid gap-4 md:grid-cols-2"><Field id="vaccination-case" label="Mã ca bệnh liên quan"><input id="vaccination-case" className={inputCls} value={healthCaseRef} disabled={readOnly} onChange={(event) => setHealthCaseRef(event.target.value)} placeholder="Ví dụ: HC-0021" /></Field><Field id="vaccination-reaction" label="Mô tả phản ứng"><input id="vaccination-reaction" className={inputCls} value={reaction} disabled={readOnly} onChange={(event) => setReaction(event.target.value)} placeholder="Không ghi nhận" /></Field></div></WorkSection>{error && <InlineMessage tone="err" title="Chưa thể lưu">{error}</InlineMessage>}<StickyActions actions={<><Button type="button" onClick={() => nav('/ui/scr-46')}>Hủy</Button><Button variant="primary" type="submit" disabled={readOnly}>Ghi nhận {codes.length || ''} mũi</Button></>} /></form></Shell>
}

function CattleHistory({ screen, role, state }: { screen: ScreenDefinition; role?: ScreenRole; state: ReviewState }) {
  const nav = useNavigate(); const [search] = useSearchParams(); const code = search.get('cattleCode') || read<{ code?: string }>(SELECTED_CATTLE, {}).code || initialCows[0]?.code || ''; const cow = cowByCode(code) || initialCows[0]; const all = sortByDate(rows().filter((item) => item.code === cow.code)); const readState = ReadState({ state, loadingLabel: 'Đang tải lịch sử của bò…', errorLabel: 'Lịch sử vaccine của bò tạm thời không khả dụng.' }); if (readState) return readState
  if (state === 'empty' || !all.length) return <Shell screen={screen}><EmptyState title="Bò chưa có dữ liệu tiêm" description="Chưa có lịch hoặc lịch sử cho cá thể này." actionLabel={isManager(role) ? 'Ghi nhận tiêm' : undefined} onAction={isManager(role) ? () => nav('/ui/scr-48') : undefined} /></Shell>; const scheduled = all.filter((item) => ['PLANNED', 'DEFERRED'].includes(item.status)); const cancelled = all.filter((item) => item.status === 'CANCELLED'); const history = all.filter(isHistoryRecord)
  return <Shell screen={screen} actions={<><Button onClick={() => nav('/ui/scr-46')}>Về lịch tiêm</Button>{isManager(role) && <Button variant="primary" onClick={() => { clearVaccinationSelection(); nav('/ui/scr-48') }}>Ghi nhận tiêm</Button>}</>}><Info items={[['Bò', `${cow.code} · ${cow.name || 'Chưa đặt tên'}`], ['Thẻ QR', cow.tag || '—'], ['Chuồng', cow.barn || '—'], ['Mũi tiếp theo', dateLabel(scheduled[0]?.planned)], ['Vaccine gần nhất', history.find((item) => item.status === 'ADMINISTERED')?.vaccine || '—']]} />{scheduled.length > 0 && <WorkSection title="Liều đã lên lịch"><Table wide scroll><thead><tr><Th>Bò</Th><Th>Chuồng</Th><Th>Lịch · mũi</Th><Th>Ngày dự kiến</Th><Th>Trạng thái</Th><Th /></tr></thead><tbody>{scheduled.map((item) => <tr key={item.id}><Td>{item.code}</Td><Td>{cow.barn || '—'}</Td><Td>{scheduleLabel(item.scheduleId)} · {item.dose}</Td><Td>{dateLabel(item.planned)}</Td><Td><Badge tone={statusTone(item)}>{statusLabel(item)}</Badge></Td><Td>{isManager(role) && state !== 'read-only' && <><Button small onClick={() => { write(SELECTED_VACCINATION, { id: item.id }); nav(selectedUrl('/ui/scr-48', item.id)) }}>Ghi nhận</Button><Button small className="ml-2" onClick={() => { write(SELECTED_VACCINATION, { id: item.id }); nav(selectedUrl('/ui/scr-50', item.id)) }}>Hoãn</Button></>}</Td></tr>)}</tbody></Table></WorkSection>}{cancelled.length > 0 && <WorkSection title="Lịch đã hủy" description="Đây là liều bị hủy do dừng lịch, không phải bản ghi tiêm bị hủy."><Table wide><thead><tr><Th>Lịch · mũi</Th><Th>Ngày dự kiến</Th><Th>Trạng thái</Th><Th>Lý do</Th></tr></thead><tbody>{cancelled.map((item) => <tr key={item.id}><Td>{scheduleLabel(item.scheduleId)} · {item.dose}</Td><Td>{dateLabel(item.planned)}</Td><Td><Badge tone="err">Lịch đã hủy</Badge></Td><Td>{item.note || '—'}</Td></tr>)}</tbody></Table></WorkSection>}<WorkSection title="Lịch sử tiêm phòng"><Table wide scroll><thead><tr><Th>Đã tiêm lúc</Th><Th>Vaccine · mũi</Th><Th>Lô · lượng</Th><Th>Ngừng thuốc</Th><Th>Nguồn</Th><Th>Người tiêm</Th><Th>Phản ứng</Th><Th>Trạng thái</Th><Th /></tr></thead><tbody>{history.map((item) => <tr key={item.id} className={item.status === 'VOIDED' ? 'text-faint line-through' : undefined}><Td>{dateTimeLabel(item.administered)}</Td><Td>{item.vaccine} · {item.dose}{item.revision ? <Badge className="ml-2" tone="outline">Sửa lần {item.revision}</Badge> : null}</Td><Td>{item.batch || 'Không rõ'} · {item.amount || 'Không rõ'}</Td><Td>{item.withdrawal || '—'}</Td><Td>{item.source === 'HISTORICAL' ? 'Lịch sử' : 'Tại trại'}</Td><Td>{item.vaccinator || item.by || 'Không rõ'}</Td><Td>{item.healthCaseRef || item.reaction || '—'}</Td><Td><Badge tone={statusTone(item)}>{item.status === 'VOIDED' ? 'Bản ghi đã hủy' : 'Đã tiêm'}</Badge></Td><Td>{isManager(role) && item.status === 'ADMINISTERED' && item.recordStatus !== 'VOIDED' && state !== 'read-only' && <Button small onClick={() => { write(SELECTED_VACCINATION, { id: item.id }); nav(selectedUrl('/ui/scr-52', item.id)) }}>Sửa · hủy</Button>}</Td></tr>)}</tbody></Table></WorkSection></Shell>
}

function DeferDose({ screen, role, state }: { screen: ScreenDefinition; role?: ScreenRole; state: ReviewState }) {
  const nav = useNavigate(); const [search] = useSearchParams(); const all = rows(); const selectedId = search.get('id') || read<{ id?: string }>(SELECTED_VACCINATION, {}).id; const selectedIds = read<string[]>(SELECTED_VACCINATIONS, []); const selected = (selectedIds.length ? selectedIds.map((id) => all.find((item) => item.id === id)) : [all.find((item) => item.id === selectedId)]).filter((item): item is Vaccination => Boolean(item)); const [date, setDate] = useState(''); const [reason, setReason] = useState(''); const [note, setNote] = useState(''); const [error, setError] = useState(''); const readState = ReadState({ state, loadingLabel: 'Đang tải biểu mẫu hoãn mũi…', errorLabel: 'Không thể tải liều cần hoãn.' }); if (readState) return readState
  if (!isManager(role) || state === 'read-only') return <Shell screen={screen}><InlineMessage tone="warn">Chỉ Quản lý ở chế độ chỉnh sửa mới được hoãn mũi tiêm.</InlineMessage></Shell>; const eligible = selected.length > 0 && selected.every(isScheduleEligible)
  const save = (event: FormEvent) => { event.preventDefault(); setError(''); if (!eligible) return setError('Chỉ các liều đang chờ hoặc đã hoãn mới được hoãn.'); if (!reason.trim()) return setError('Lý do không tiêm là bắt buộc.'); if (date && date < localToday()) return setError('Ngày mới phải là hôm nay hoặc một ngày sau đó.'); if (date && selected.some((item) => entryDate(cowByCode(item.code)) && date < entryDate(cowByCode(item.code)!))) return setError('Ngày dự kiến mới không được trước ngày nhập đàn.'); const latest = rows(); const updated = latest.map((item) => selected.some((row) => row.id === item.id) ? { ...item, planned: date || item.planned, deferDate: date || undefined, status: 'DEFERRED' as const, note: `${reason.trim()}${note.trim() ? ` · ${note.trim()}` : ''}`, recordStatus: undefined, source: undefined, administered: undefined, route: undefined, amount: undefined, withdrawal: undefined, withdrawalDays: undefined, vaccinator: undefined, by: undefined } : item); write('vaccination-preview', updated); const reminders = read<Array<Record<string, unknown>>>('vaccination-reminders', []); write('vaccination-reminders', [...selected.map((item) => ({ id: `reminder-${item.id}`, code: item.code, scheduleId: item.scheduleId, dose: item.dose, due: date || item.planned, status: 'OPEN' })), ...reminders.filter((item) => !selected.some((row) => item.id === `reminder-${row.id}`))]); write(SELECTED_VACCINATIONS, []); write(SELECTED_VACCINATION, null); nav('/ui/scr-46') }
  return <Shell screen={screen}><Info items={[["Số mũi", selected.length], ["Bò", selected.map((item) => item.code).join(', ') || '—'], ["Ngày dự kiến cũ", selected.map((item) => dateLabel(item.planned)).join(', ') || '—'], ["Vaccine", [...new Set(selected.map((item) => item.vaccine))].join(', ') || '—']]} /><form id="vaccination-defer-form" onSubmit={save} className="max-w-4xl space-y-5"><WorkSection title="Lý do hoãn"><Field id="vaccination-defer-date" label="Ngày dự kiến mới (tuỳ chọn)"><input id="vaccination-defer-date" className={inputCls} type="date" min={localToday()} value={date} onChange={(event) => setDate(event.target.value)} /></Field><InlineMessage tone="info">Để trống để giữ nguyên ngày dự kiến hiện tại.</InlineMessage><Field id="vaccination-defer-reason" label="Lý do không tiêm *"><textarea id="vaccination-defer-reason" className={inputCls} maxLength={500} rows={4} value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Ví dụ: Bò đang sốt, chờ bác sĩ đánh giá" /></Field><Field id="vaccination-defer-note" label="Ghi chú"><textarea id="vaccination-defer-note" className={inputCls} maxLength={255} rows={2} value={note} onChange={(event) => setNote(event.target.value)} /></Field></WorkSection>{!eligible && <InlineMessage tone="err">Không tìm thấy liều đang chờ hoặc đã hoãn phù hợp.</InlineMessage>}{error && <InlineMessage tone="err" title="Chưa thể lưu">{error}</InlineMessage>}<StickyActions actions={<><Button type="button" onClick={() => { write(SELECTED_VACCINATIONS, []); nav('/ui/scr-46') }}>Hủy</Button><Button variant="primary" type="submit">Lưu hoãn {selected.length} mũi</Button></>} /></form></Shell>
}

function History({ screen, state }: { screen: ScreenDefinition; state: ReviewState }) {
  const nav = useNavigate(); const all = sortByDate(rows().filter(isHistoryRecord)); const [query, setQuery] = useState(''); const [vaccine, setVaccine] = useState('ALL'); const [source, setSource] = useState('ALL'); const [from, setFrom] = useState(''); const [to, setTo] = useState(''); const [period, setPeriod] = useState('3'); const readState = ReadState({ state, loadingLabel: 'Đang tải lịch sử tiêm toàn đàn…', errorLabel: 'Lịch sử tiêm toàn đàn tạm thời không khả dụng.' }); if (readState) return readState; const cutoff = period === 'ALL' ? '' : addDays(localToday(), -Number(period) * 30); const visible = all.filter((item) => { const date = item.administered?.slice(0, 10) || ''; return (!query || `${item.code} ${cowByCode(item.code)?.tag || ''} ${cowByCode(item.code)?.barn || ''}`.toLowerCase().includes(query.toLowerCase())) && (vaccine === 'ALL' || item.vaccine === vaccine) && (source === 'ALL' || item.source === source) && (!cutoff || date >= cutoff) && (!from || date >= from) && (!to || date <= to) }); if (state === 'empty') return <Shell screen={screen}><EmptyState title="Chưa có lịch sử tiêm" description="Chỉ các mũi đã tiêm hợp lệ hoặc đã hủy mới xuất hiện ở đây." actionLabel="Về lịch tiêm" onAction={() => nav('/ui/scr-46')} /></Shell>
  return <Shell screen={screen} actions={<Button onClick={() => nav('/ui/scr-46')}>Về lịch tiêm</Button>}><FilterBar><Field id="history-query" label="Tìm bò, thẻ hoặc chuồng"><input id="history-query" aria-label="Tìm bò, thẻ hoặc chuồng" className={inputCls} value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Mã bò hoặc thẻ QR" /></Field><Field id="history-vaccine" label="Vaccine"><select id="history-vaccine" aria-label="Lọc vaccine lịch sử" className={inputCls} value={vaccine} onChange={(event) => setVaccine(event.target.value)}><option value="ALL">Tất cả vaccine</option>{[...new Set(all.map((item) => item.vaccine))].map((item) => <option key={item}>{item}</option>)}</select></Field><Field id="history-source" label="Nguồn"><select id="history-source" aria-label="Lọc nguồn" className={inputCls} value={source} onChange={(event) => setSource(event.target.value)}><option value="ALL">Tất cả nguồn</option><option value="ON_FARM">Tại trại</option><option value="HISTORICAL">Lịch sử</option></select></Field><Field id="history-period" label="Khoảng nhanh"><select id="history-period" aria-label="Khoảng thời gian" className={inputCls} value={period} onChange={(event) => setPeriod(event.target.value)}><option value="3">3 tháng gần đây</option><option value="12">12 tháng gần đây</option><option value="ALL">Toàn bộ</option></select></Field><div className="grid grid-cols-2 gap-2"><Field id="history-from" label="Từ ngày"><input id="history-from" aria-label="Từ ngày" className={inputCls} type="date" value={from} onChange={(event) => setFrom(event.target.value)} /></Field><Field id="history-to" label="Đến ngày"><input id="history-to" aria-label="Đến ngày" className={inputCls} type="date" value={to} onChange={(event) => setTo(event.target.value)} /></Field></div><Button small onClick={() => { setQuery(''); setVaccine('ALL'); setSource('ALL'); setFrom(''); setTo(''); setPeriod('3') }}>Xóa lọc</Button></FilterBar><SummaryStrip items={[{ label: 'Bản ghi hợp lệ', value: visible.filter((item) => item.status === 'ADMINISTERED').length }, { label: 'Tại trại', value: visible.filter((item) => item.source === 'ON_FARM').length }, { label: 'Khai báo lịch sử', value: visible.filter((item) => item.source === 'HISTORICAL').length }, { label: 'Đã hủy', value: visible.filter((item) => item.status === 'VOIDED').length }]} />{!visible.length ? <EmptyState title="Không có bản ghi phù hợp" description="Thử mở rộng khoảng thời gian hoặc bỏ bớt bộ lọc." actionLabel="Xóa bộ lọc" onAction={() => { setQuery(''); setVaccine('ALL'); setSource('ALL'); setFrom(''); setTo(''); setPeriod('3') }} /> : <Table wide scroll><thead><tr><Th>Đã tiêm lúc</Th><Th>Bò · chuồng</Th><Th>Vaccine · mũi</Th><Th>Lô · lượng</Th><Th>Nguồn</Th><Th>Người tiêm</Th><Th>Phản ứng</Th><Th>Trạng thái</Th><Th /></tr></thead><tbody>{visible.map((item) => <tr key={item.id} className={item.status === 'VOIDED' ? 'text-faint line-through' : undefined}><Td>{dateTimeLabel(item.administered)}</Td><Td>{item.code} · {cowByCode(item.code)?.barn || '—'}</Td><Td>{item.vaccine} · {item.dose}{item.revision ? <Badge className="ml-2" tone="outline">Sửa lần {item.revision}</Badge> : null}</Td><Td>{item.batch || 'Không rõ'} · {item.amount || 'Không rõ'}</Td><Td>{item.source === 'HISTORICAL' ? 'Lịch sử' : item.source === 'ON_FARM' ? 'Tại trại' : '—'}</Td><Td>{item.vaccinator || item.by || 'Không rõ'}</Td><Td>{item.healthCaseRef || item.reaction || '—'}</Td><Td><Badge tone={statusTone(item)}>{item.status === 'VOIDED' ? 'Bản ghi đã hủy' : 'Đã tiêm'}</Badge></Td><Td><Button small onClick={() => { write(SELECTED_CATTLE, { code: item.code }); write(SELECTED_VACCINATION, { id: item.id }); nav(selectedUrl('/ui/scr-49', item.id)) }}>Mở</Button></Td></tr>)}</tbody></Table>}</Shell>
}

function CorrectOrVoid({ screen, role, state }: { screen: ScreenDefinition; role?: ScreenRole; state: ReviewState }) {
  const nav = useNavigate(); const [search] = useSearchParams(); const all = rows(); const id = search.get('id') || read<{ id?: string }>(SELECTED_VACCINATION, {}).id; const current = id ? all.find((item) => item.id === id) : undefined; const [action, setAction] = useState<'CORRECT' | 'VOID'>('CORRECT'); const [vaccine, setVaccine] = useState(current?.vaccine || ''); const [batch, setBatch] = useState(current?.batch || ''); const [date, setDate] = useState(current?.administered?.slice(0, 10) || ''); const [time, setTime] = useState(current?.administered?.split('T')[1]?.slice(0, 5) || localNow().time); const [amount, setAmount] = useState(current?.amount || ''); const [route, setRoute] = useState<Route>((current?.route as Route) || 'Tiêm bắp'); const [withdrawalDays, setWithdrawalDays] = useState(String(current?.withdrawalDays ?? 0)); const [vaccinator, setVaccinator] = useState(current?.vaccinator || current?.by || ''); const [reason, setReason] = useState(''); const [confirmed, setConfirmed] = useState(false); const [error, setError] = useState(''); const readState = ReadState({ state, loadingLabel: 'Đang tải bản ghi tiêm…', errorLabel: 'Bản ghi tiêm tạm thời không khả dụng.' }); if (readState) return readState
  if (!isManager(role) || state === 'read-only') return <Shell screen={screen}><InlineMessage tone="warn">Chỉ Quản lý ở chế độ chỉnh sửa mới được điều chỉnh bản ghi.</InlineMessage></Shell>; if (!current || current.status !== 'ADMINISTERED' || current.recordStatus === 'VOIDED') return <Shell screen={screen}><InlineMessage tone="err" title="Không thể điều chỉnh">Không tìm thấy bản ghi tiêm hợp lệ từ lựa chọn hiện tại. Không tự mở bản ghi khác.</InlineMessage><Button onClick={() => nav('/ui/scr-51')}>Về lịch sử</Button></Shell>
  const save = (event: FormEvent) => { event.preventDefault(); setError(''); if (!confirmed) return setError('Hãy xác nhận bản ghi và hậu quả của thao tác trước khi lưu.'); if (!reason.trim()) return setError('Lý do điều chỉnh là bắt buộc.'); if (action === 'CORRECT' && (!isActiveVaccine(vaccine) || !batch.trim() || !date || !time || !amount.trim() || !vaccinator.trim())) return setError('Vaccine đang sử dụng, số lô, thời gian, lượng dùng và người tiêm là bắt buộc khi sửa.'); if (action === 'CORRECT' && (!isValidRoute(route) || !Number.isFinite(Number(withdrawalDays)) || Number(withdrawalDays) < 0 || Number(withdrawalDays) > 365)) return setError('Kiểm tra đường dùng và thời gian ngừng thuốc.'); if (action === 'CORRECT' && (date > localToday() || (date === localToday() && time > localNow().time))) return setError('Thời gian mới không được ở tương lai.'); if (action === 'CORRECT' && entryDate(cowByCode(current.code)) && date < entryDate(cowByCode(current.code)!)) return setError('Thời gian mới không được trước ngày nhập đàn.'); const revisions = read<Revision[]>('vaccination-revisions', []); const revisionNumber = revisions.filter((item) => item.originalId === current.id).length + 1; const actor = MANAGER; const next: Vaccination = action === 'VOID' ? { ...current, status: 'VOIDED', recordStatus: 'VOIDED', updatedBy: actor, note: reason.trim(), withdrawal: undefined } : { ...current, vaccine, batch: batch.trim(), administered: `${date}T${time}`, amount: amount.trim(), route, withdrawalDays: Number(withdrawalDays), withdrawal: Number(withdrawalDays) > 0 ? addDays(date, Number(withdrawalDays)) : undefined, vaccinator: vaccinator.trim(), by: vaccinator.trim(), status: 'ADMINISTERED', recordStatus: 'VALID', revision: revisionNumber, updatedBy: actor, note: reason.trim() }; const revision: Revision = { id: `vax-revision-${Date.now()}`, originalId: current.id, action, reason: reason.trim(), actor, revision: revisionNumber, before: { ...current }, after: next, createdAt: new Date().toISOString() }; write('vaccination-revisions', [revision, ...revisions]); let updated = all.map((item) => item.id === current.id ? next : item); if (action === 'VOID' && current.scheduleId && current.scheduledPriorStatus) { const restoreId = `schedule-restore-${current.scheduleId}-${current.code}-${current.dose.replace(/\s/g, '-')}`; const restored: Vaccination = { ...current, id: restoreId, status: current.scheduledPriorStatus, recordStatus: undefined, source: undefined, administered: undefined, batch: '', amount: undefined, route: undefined, withdrawal: undefined, withdrawalDays: undefined, vaccinator: undefined, by: undefined, note: `Khôi phục sau khi hủy bản ghi ${current.id}`, revision: undefined }; updated = [...updated.filter((item) => item.id !== restoreId), restored]; const reminders = read<Array<Record<string, unknown>>>('vaccination-reminders', []); write('vaccination-reminders', [{ id: `reminder-${restoreId}`, code: current.code, scheduleId: current.scheduleId, dose: current.dose, due: restored.planned, status: 'OPEN' }, ...reminders.filter((item) => item.id !== `reminder-${restoreId}`)]); } write('vaccination-preview', updated); recomputeWithdrawal(current.code, updated); nav(selectedUrl('/ui/scr-49', current.id)) }
  return <Shell screen={screen}><Info items={[['Bản ghi gốc (bất biến)', `${current.vaccine} · ${current.batch} · ${dateTimeLabel(current.administered)}`], ['Bò', current.code], ['Lịch · mũi', `${scheduleLabel(current.scheduleId)} · ${current.dose}`], ['Người tiêm gốc', current.vaccinator || current.by || '—'], ['Thao tác', action === 'VOID' ? 'Hủy bản ghi tiêm' : 'Tạo phiên bản chỉnh sửa']]} /><form id="vaccination-correction-form" onSubmit={save} className="min-w-0 space-y-6"><InlineMessage tone="info">Bản ghi gốc không bị sửa im lặng. Mỗi lần sửa hoặc hủy tạo một phiên bản lịch sử, kèm người thực hiện, lý do và giá trị trước/sau.</InlineMessage><WorkSection title="Kiểu xử lý"><Field id="vaccination-action" label="Thao tác *"><select id="vaccination-action" className={inputCls} value={action} onChange={(event) => { setAction(event.target.value as 'CORRECT' | 'VOID'); setConfirmed(false) }}><option value="CORRECT">Sửa bản ghi</option><option value="VOID">Hủy bản ghi tiêm</option></select></Field></WorkSection><WorkSection title="Giá trị mới (chỉ dùng khi sửa)"><div className="grid gap-4 md:grid-cols-3"><Field id="correction-vaccine" label="Vaccine mới *"><select id="correction-vaccine" className={inputCls} value={vaccine} disabled={action === 'VOID'} onChange={(event) => setVaccine(event.target.value)}>{vaccineChoices().map((item) => <option key={item}>{item}</option>)}</select></Field><Field id="correction-batch" label="Số lô mới *"><input id="correction-batch" className={inputCls} value={batch} disabled={action === 'VOID'} onChange={(event) => setBatch(event.target.value)} /></Field><Field id="correction-date" label="Ngày mới *"><input id="correction-date" className={inputCls} type="date" max={localToday()} value={date} disabled={action === 'VOID'} onChange={(event) => setDate(event.target.value)} /></Field><Field id="correction-time" label="Giờ mới *"><input id="correction-time" className={inputCls} type="time" value={time} disabled={action === 'VOID'} onChange={(event) => setTime(event.target.value)} /></Field><Field id="correction-amount" label="Lượng dùng mới *"><input id="correction-amount" className={inputCls} value={amount} disabled={action === 'VOID'} onChange={(event) => setAmount(event.target.value)} /></Field><Field id="correction-route" label="Đường dùng"><select id="correction-route" className={inputCls} value={route} disabled={action === 'VOID'} onChange={(event) => setRoute(event.target.value as Route)}>{ROUTE_OPTIONS.map((item) => <option key={item}>{item}</option>)}</select></Field><Field id="correction-withdrawal" label="Ngừng thuốc (ngày)"><input id="correction-withdrawal" className={inputCls} type="number" min="0" max="365" value={withdrawalDays} disabled={action === 'VOID'} onChange={(event) => setWithdrawalDays(event.target.value)} /></Field><Field id="correction-vaccinator" label="Người tiêm mới *"><input id="correction-vaccinator" className={inputCls} value={vaccinator} disabled={action === 'VOID'} onChange={(event) => setVaccinator(event.target.value)} /></Field></div></WorkSection><Field id="correction-reason" label="Lý do điều chỉnh *"><textarea id="correction-reason" className={inputCls} maxLength={500} rows={4} value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Nêu rõ sai lệch và lý do sửa hoặc hủy" /></Field><label htmlFor="vaccination-confirm" className="flex items-start gap-2 text-sm"><input id="vaccination-confirm" type="checkbox" checked={confirmed} onChange={(event) => setConfirmed(event.target.checked)} /><span>Tôi xác nhận đã kiểm tra bản ghi, lý do và liên kết lịch; thao tác này sẽ tạo một phiên bản lịch sử{action === 'VOID' ? ' và khôi phục liều lịch nếu có.' : '.'}</span></label>{error && <InlineMessage tone="err" title="Chưa thể lưu">{error}</InlineMessage>}<StickyActions actions={<><Button type="button" onClick={() => nav('/ui/scr-49')}>Hủy</Button><Button variant={action === 'VOID' ? 'danger' : 'primary'} type="submit">{action === 'VOID' ? 'Hủy bản ghi' : 'Lưu chỉnh sửa'}</Button></>} /></form></Shell>
}

export function VaccinationPreviewScreen({ screen, role, state = 'success' }: { screen: ScreenDefinition; role?: ScreenRole; state?: ReviewState }) { if (screen.id === 'SCR-46') return <Schedule screen={screen} role={role} state={state} />; if (screen.id === 'SCR-47') return <ScheduleEditor screen={screen} role={role} state={state} />; if (screen.id === 'SCR-48') return <RecordVaccination screen={screen} role={role} state={state} />; if (screen.id === 'SCR-49') return <CattleHistory screen={screen} role={role} state={state} />; if (screen.id === 'SCR-50') return <DeferDose screen={screen} role={role} state={state} />; if (screen.id === 'SCR-51') return <History screen={screen} state={state} />; return <CorrectOrVoid screen={screen} role={role} state={state} /> }
